SELECT * FROM asset_category
WHERE level = 2

    AND parent_id = #{parentId}


    AND status = #{status}


    AND category_name LIKE CONCAT('%', #{categoryName}, '%')

ORDER BY category_code

SELECT ac3.* FROM asset_category ac3
WHERE ac3.level = 3

    
        
        AND ac3.parent_id = #{parentId}
    
    
        
        AND EXISTS (
            SELECT 1 FROM asset_category ac2 
            WHERE ac2.id = ac3.parent_id 
            AND ac2.level = 2 
            AND ac2.parent_id = #{level1Id}
        )
    


    AND ac3.status = #{status}


    AND ac3.category_name LIKE CONCAT('%', #{categoryName}, '%')

ORDER BY ac3.category_code

